diff --git a/expat/lib/xmlparse.c b/expat/lib/xmlparse.c
index 8d5d86e..ecd7e96 100644
--- a/expat/lib/xmlparse.c
+++ b/expat/lib/xmlparse.c
@@ -2386,6 +2386,11 @@ XML_Parse(XML_Parser parser, const char *s, int len, int isFinal) {
   if (len > 0) {
     assert(s != NULL); // make sure s==NULL && len!=0 was rejected above
     memcpy(buff, s, len);
+    /* First growth rounds a 2047-byte fill up to the initial block, so
+       the extra byte is still inside a fresh block.  Define it. */
+    if ((unsigned)len + 1u == (unsigned)INIT_BUFFER_SIZE * 2u
+        && parser->m_bufferEnd == parser->m_buffer)
+      ((char *)buff)[len] = '\0';
   }
   return XML_ParseBuffer(parser, len, isFinal);
 }

